return items.map(item => {
    const raw = (item.json.title || '').toString().trim();

    let firstName = '';
    let lastName = '';

    // Find the @username inside parentheses if present
    const atWithParenMatch = raw.match(/\(@([^\s)]+)\)/);

    if (atWithParenMatch) {
        // Extract just the handle part, without the @
        lastName = atWithParenMatch[1].trim();

        // Remove only this @ parentheses section from the string
        const withoutAtParen = raw.replace(atWithParenMatch[0], '').trim();

        // Remove all *remaining* parentheses and content
        firstName = withoutAtParen.replace(/\([^)]*\)/g, '').trim();
    } else {
        // No @ handle section, so just remove parentheses and content
        firstName = raw.replace(/\([^)]*\)/g, '').trim();
    }

    return {
        json: {
            firstName,
            lastName
        }
    };
});
